import os

file_path = r"C:\Users\Boaz\Desktop\WB_Blog_Drafts\penal-substitution\wb_penal-substitution-13-reconciliation-2.md"

with open(file_path, 'r', encoding='utf-8') as f:
    content = f.read()

target = """## ١. الاتحاد السري: لا مصالحة خارج المسيح (Unio Mystica)
المصالحة في الفكر الكتابي ليست مجرد "خيال قانوني" (Legal Fiction)؛ كأن يعلن القاضي براءة متهم غائب لا يربطه بالشفيع أي رابط. كلا، بل هي مبنية على حقيقة روحية وكيانية عميقة. مفتاح فهم المصالحة يكمن في حرف الجر العظيم الذي كرره بولس الرسول مئات المرات: **"فِي الْمَسِيحِ"**.

يعلمنا اللاهوت المصلح أن كل بركات الخلاص—من اختيار، تبرير، مصالحة، وتقديس—تصل إلينا حصرياً عبر قناة واحدة: "الاتحاد السري بالمسيح" [^1]. حين نؤمن، لا يقف المسيح بعيداً عنا ليعطينا صك المصالحة، بل يوحدنا الروح القدس به. نحن نلبسه كأعضاء في جسده. ولأننا "فيه"، فما هو له (الحياة والبر) يصير لنا، وما هو لنا (الموت واللعنة) صار له على الصليب. لا توجد مصالحة معلّقة في الهواء؛ إما أنك "فِي الْمَسِيحِ" مصالح ومبرر، أو أنك خارج المسيح تحت الدينونة. 

حينما سُرَّ الآب أن يسحقه بالحزن ليصنع الترضية، كان ذلك لكي نتحد نحن بالمسيح المصلوب والمُقام، فيُنظر إلينا لا في عرينا وتلوثنا، بل في كمال الابن المحبوب."""

replacement = """## ١. الاتحاد السري: لا مصالحة خارج المسيح (Unio Mystica)
المصالحة في الفكر الكتابي ليست مجرد "خيال قانوني" (Legal Fiction)؛ كأن يعلن القاضي براءة متهم غائب لا يربطه بالشفيع أي رابط. كلا، بل هي مبنية على حقيقة روحية وكيانية عميقة. في الواقع، يعتبر اللاهوت المصلح أن "الاتحاد بالمسيح" ليس مجرد فكرة فرعية، بل هو الحقيقة المركزية التي يدور حولها الخلاص بأكمله [^4]. مفتاح فهم هذه المصالحة يكمن في حرف الجر العظيم الذي كرره بولس الرسول ١٦٤ مرة في رسائله: **"فِي الْمَسِيحِ"**.

يعلمنا اللاهوت المصلح أن كل بركات الخلاص—من اختيار، تبرير، مصالحة، وتقديس—تصل إلينا حصرياً عبر قناة واحدة: "الاتحاد السري بالمسيح" [^1]. حين نؤمن، لا يقف المسيح بعيداً عنا ليعطينا صك المصالحة، بل يوحدنا الروح القدس به. نحن نلبسه كأعضاء في جسده. ولأننا "فيه"، فما هو له (الحياة والبر) يصير لنا، وما هو لنا (الموت واللعنة) صار له على الصليب. لا توجد مصالحة معلّقة في الهواء؛ إما أنك "فِي الْمَسِيحِ" مصالح ومبرر، أو أنك خارج المسيح تحت الدينونة. 

هذا الاتحاد يحفظ التمايز المجيد بين الخالق والمخلوق؛ فهو ليس ذوباناً صوفياً (Absorptive Mysticism) تتلاشى فيه هويتنا البشرية في الألوهية، ولا هو مجرد اتحاد أسراري طقسي (Sacramental Union)، بل هو اتحاد عضوي حميم وفعّال بالروح القدس [^5]. لقد لخص آباء الكنيسة الأوائل، مثل القديس إيريناوس، عظمة هذا السر بعبارته الشهيرة: *"صار ابن الله ابناً للإنسان لكي يصير أبناء البشر أبناءً لله"*. لقد اتحد بطبيعتنا البشرية وسُحق بالحزن ليصنع الترضية، لكي نتحد نحن بطبيعته المُقامة، فيُنظر إلينا لا في عرينا وتلوثنا، بل في كمال الابن المحبوب.

وهذا الاتحاد يمتد حتى لواقعنا العملي المتألم؛ فبما أننا "فيه"، فنحن نشترك أيضاً في آلامه. المصالحة لا تعني غياب الألم، بل تعني أننا في أتون التجربة لسنا وحدنا، بل نحن امتداد لجسد المسيح المتألم، مما يمنحنا فرحاً مجيداً وسط الضيقات لأننا شركاء معه [^6]."""

footnotes = """
[^4]: يرى العديد من اللاهوتيين المصلحين، وعلى رأسهم چون موراي (John Murray)، أن الاتحاد بالمسيح ليس مجرد خطوة في طريق الخلاص، بل هو الحقيقة المركزية التي تكمن وراء كل جانب من جوانب الفداء.
[^5]: يحذر علم اللاهوت النظامي (Systematic Theology) من الانحرافات التاريخية لفهم الاتحاد بالمسيح؛ مثل الاستيعاب الصوفي (Absorptive Mysticism) الذي يمحو الفارق بين الخالق والمخلوق ويميل للحلولية، أو الاتحاد الأسراري (Sacramental Union) في اللاهوت الكاثوليكي الذي يربط الاتحاد حصرياً بتناول الإفخارستيا بمعزل عن الإيمان والروح القدس.
[^6]: يشرح اللاهوتي چون بايبر (John Piper) في مفهومه عن الفرح المسيحي (Christian Hedonism) أن اتحادنا بالمسيح يجعل آلامنا ليست مجرد آلام شخصية، بل هي شركة في آلام المسيح نفسه، وهو ما يدفعنا للفرح وسط الألم كما يقتبس من شهادة القس چوزيف تسون تحت الاضطهاد: "أنا لست مقاتلاً وحيداً؛ أنا امتداد ليسوع المسيح... لم تكن آلامي، بل كان لي شرف مشاركته آلامه"."""

if target in content:
    content = content.replace(target, replacement)
    content += footnotes
    with open(file_path, 'w', encoding='utf-8') as f:
        f.write(content)
    print("Replaced content and added footnotes successfully.")
else:
    print("Error: Target text not found.")
